1	// Package indexroom implements chain ingestion with reorg handling and
2	// consistent paginated transaction queries over the main chain.
3	package indexroom
4	
5	import "sync"
6	
7	// Block is one ingested block with its transactions.
8	type Block struct {
9		Height int64
10		Hash   string
11		Parent string
12		Txs    []string
13	}
14	
15	// Index is the durable chain view.
16	//
17	// Append, Reorg, and QueryTxs are safe for concurrent use; the exported
18	// fields are meant for read-only inspection after all calls have finished.
19	type Index struct {
20		Blocks map[int64]Block
21		ByHash map[string]int64
22		Tip    int64
23	
24		mu  sync.Mutex
25		key [32]byte
26	}
27	
28	// New returns an empty index.
29	func New() *Index {
30		return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
31	}
32	
33	// Append accepts a block only when it extends the current tip, keeping the
34	// chain linear. Re-submitting a block identical to one already on the main
35	// chain is a successful no-op. A rejected append leaves the index untouched.
36	func (index *Index) Append(block Block) error {
37		index.mu.Lock()
38		defer index.mu.Unlock()
39		return index.appendLocked(block)
40	}
41	
42	func (index *Index) appendLocked(block Block) error {
43		if block.Hash == "" {
44			return errInvalid("block needs a hash")
45		}
46		if index.Tip == 0 {
47			// Empty index: only the first block at height 1 is accepted; its
48			// parent becomes the chain start identifier and need not be indexed.
49			if block.Height != 1 {
50				return errInvalid("first block must be at height 1")
51			}
52			index.storeLocked(block)
53			return nil
54		}
55		if old, exists := index.Blocks[block.Height]; exists {
56			if sameBlock(old, block) {
57				return nil
58			}
59			return errInvalid("height already indexed with different content")
60		}
61		if block.Height != index.Tip+1 {
62			return errInvalid("block height must extend the current tip")
63		}
64		if block.Parent != index.Blocks[index.Tip].Hash {
65			return errInvalid("parent does not match the current tip")
66		}
67		if _, exists := index.ByHash[block.Hash]; exists {
68			return errInvalid("hash already indexed at another height")
69		}
70		index.storeLocked(block)
71		return nil
72	}
73	
74	// Reorg replaces the tip range with an alternate branch and reports the
75	// dropped old heights in ascending order. The branch is validated in full
76	// before anything is applied, so a rejected reorg leaves the index exactly
77	// as it was. Heights whose old block is identical to the new one are not
78	// reported; re-submitting the branch already in effect returns an empty list.
79	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
80		index.mu.Lock()
81		defer index.mu.Unlock()
82	
83		if len(blocks) == 0 {
84			return nil, errInvalid("empty branch")
85		}
86		ancestor, ok := index.ByHash[blocks[0].Parent]
87		if !ok {
88			return nil, errInvalid("branch parent is unknown")
89		}
90		if blocks[0].Height != ancestor+1 {
91			return nil, errInvalid("branch must start at the ancestor height plus one")
92		}
93		seen := make(map[string]bool, len(blocks))
94		for i, block := range blocks {
95			if block.Hash == "" {
96				return nil, errInvalid("block needs a hash")
97			}
98			if seen[block.Hash] {
99				return nil, errInvalid("duplicate hash inside branch")
100			}
101			seen[block.Hash] = true
102			if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
103				return nil, errInvalid("hash conflicts with a retained block")
104			}
105			if i > 0 {
106				prev := blocks[i-1]
107				if block.Height != prev.Height+1 {
108					return nil, errInvalid("branch heights must be consecutive")
109				}
110				if block.Parent != prev.Hash {
111					return nil, errInvalid("branch parent does not match the previous block")
112				}
113			}
114		}
115	
116		// Everything validated; compute the dropped heights before mutating.
117		newTip := blocks[len(blocks)-1].Height
118		dropped := []int64{}
119		for height := ancestor + 1; height <= index.Tip; height++ {
120			if height > newTip {
121				dropped = append(dropped, height)
122				continue
123			}
124			if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
125				dropped = append(dropped, height)
126			}
127		}
128		for height := ancestor + 1; height <= index.Tip; height++ {
129			delete(index.ByHash, index.Blocks[height].Hash)
130			delete(index.Blocks, height)
131		}
132		index.Tip = ancestor
133		for _, block := range blocks {
134			index.storeLocked(block)
135		}
136		return dropped, nil
137	}
138	
139	// storeLocked records a validated block, copying its transactions so later
140	// caller-side mutation of the slice cannot alter the stored block.
141	func (index *Index) storeLocked(block Block) {
142		if block.Txs != nil {
143			txs := make([]string, len(block.Txs))
144			copy(txs, block.Txs)
145			block.Txs = txs
146		}
147		index.Blocks[block.Height] = block
148		index.ByHash[block.Hash] = block.Height
149		index.Tip = block.Height
150	}
151	
152	// sameBlock reports whether two blocks are identical: same height, hash,
153	// parent, and transactions in order. An empty tx list equals a missing one.
154	func sameBlock(a, b Block) bool {
155		if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
156			return false
157		}
158		if len(a.Txs) != len(b.Txs) {
159			return false
160		}
161		for i := range a.Txs {
162			if a.Txs[i] != b.Txs[i] {
163				return false
164			}
165		}
166		return true
167	}
168	
169	type errInvalid string
170	
171	func (e errInvalid) Error() string { return string(e) }
