111	func TestAppendStoresCopyOfTxs(t *testing.T) {
112		index := New()
113		txs := []string{"t1", "t2"}
114		if err := index.Append(Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: txs}); err != nil {
115			t.Fatal(err)
116		}
117		txs[0] = "mutated"
118		if got := index.Blocks[1].Txs; !reflect.DeepEqual(got, []string{"t1", "t2"}) {
119			t.Fatalf("stored txs changed by caller mutation: %v", got)
120		}
121	}
122	
123	func TestReorgReplacesSuffixAndReportsDropped(t *testing.T) {
124		index := chain(t,
125			Block{Height: 1, Hash: "h1", Parent: "genesis"},
126			Block{Height: 2, Hash: "h2", Parent: "h1"},
127			Block{Height: 3, Hash: "h3", Parent: "h2"},
128		)
129		dropped, err := index.Reorg([]Block{
130			{Height: 2, Hash: "h2b", Parent: "h1"},
131			{Height: 3, Hash: "h3b", Parent: "h2b"},
132			{Height: 4, Hash: "h4b", Parent: "h3b"},
133		})
134		if err != nil {
135			t.Fatalf("reorg refused: %v", err)
136		}
137		if !reflect.DeepEqual(dropped, []int64{2, 3}) {
138			t.Fatalf("dropped=%v, want [2 3]", dropped)
139		}
140		if index.Tip != 4 {
141			t.Fatalf("tip=%d, want 4", index.Tip)
142		}
143		for _, hash := range []string{"h2", "h3"} {
144			if _, ok := index.ByHash[hash]; ok {
145				t.Fatalf("removed hash %s still indexed", hash)
146			}
147		}
148		if block, ok := index.Blocks[2]; !ok || block.Hash != "h2b" {
149			t.Fatalf("height 2 not replaced: %+v", index.Blocks[2])
150		}
151	}
152	
153	func TestReorgShorterBranchTruncates(t *testing.T) {
154		index := chain(t,
155			Block{Height: 1, Hash: "h1", Parent: "genesis"},
156			Block{Height: 2, Hash: "h2", Parent: "h1"},
157			Block{Height: 3, Hash: "h3", Parent: "h2"},
158		)
159		dropped, err := index.Reorg([]Block{{Height: 3, Hash: "h3b", Parent: "h2"}})
160		if err != nil {
161			t.Fatalf("reorg refused: %v", err)
162		}
163		if !reflect.DeepEqual(dropped, []int64{3}) {
164			t.Fatalf("dropped=%v, want [3]", dropped)
165		}
166		if index.Tip != 3 || index.Blocks[3].Hash != "h3b" {
167			t.Fatalf("unexpected tip state: tip=%d block=%+v", index.Tip, index.Blocks[3])
168		}
169		if _, ok := index.ByHash["h3"]; ok {
170			t.Fatal("old hash h3 still indexed")
171		}
172	}
173	
174	func TestReorgIdenticalBlocksNotReported(t *testing.T) {
175		index := chain(t,
176			Block{Height: 1, Hash: "h1", Parent: "genesis"},
177			Block{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t1"}},
178			Block{Height: 3, Hash: "h3", Parent: "h2"},
179		)
180		// Height 2 is identical to the stored block (nil vs empty txs), only 3 differs.
181		dropped, err := index.Reorg([]Block{
182			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t1"}},
183			{Height: 3, Hash: "h3b", Parent: "h2"},
184		})
185		if err != nil {
186			t.Fatalf("reorg refused: %v", err)
187		}
188		if !reflect.DeepEqual(dropped, []int64{3}) {
189			t.Fatalf("dropped=%v, want [3]", dropped)
190		}
191		// Re-submitting the branch now in effect succeeds with an empty list.
192		dropped, err = index.Reorg([]Block{
193			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"t1"}},
194			{Height: 3, Hash: "h3b", Parent: "h2"},
195		})
196		if err != nil {
197			t.Fatalf("idempotent reorg refused: %v", err)
198		}
199		if len(dropped) != 0 {
200			t.Fatalf("dropped=%v, want empty", dropped)
201		}
202		if index.Tip != 3 {
203			t.Fatalf("tip=%d, want 3", index.Tip)
204		}
205	}
206	
207	func TestReorgFailureLeavesStateUntouched(t *testing.T) {
208		build := func(t *testing.T) *Index {
