package indexroom

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

// ErrInvalidSnapshot marks a rejected snapshot document: malformed JSON,
// trailing data, an unknown version, missing or mistyped fields, duplicate
// fields, non-consecutive heights, empty or duplicated hashes, a broken
// parent link, or a tip that disagrees with the block list. A rejected
// restore never changes the index.
var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")

// snapshotVersion is the only snapshot layout this package reads and writes.
const snapshotVersion = 1

// snapshotDoc is the wire form of an exported main chain.
type snapshotDoc struct {
	Version int64           `json:"version"`
	Tip     int64           `json:"tip"`
	Blocks  []snapshotBlock `json:"blocks"`
}

// snapshotBlock is the wire form of one block inside a snapshot.
type snapshotBlock struct {
	Height int64    `json:"height"`
	Hash   string   `json:"hash"`
	Parent string   `json:"parent"`
	Txs    []string `json:"txs"`
}

// Export writes the current main chain to w as a JSON snapshot...
func (index *Index) Export(w io.Writer) error {
	index.mu.Lock()
	doc := snapshotDoc{
		Version: snapshotVersion,
		Tip:     index.Tip,
		Blocks:  make([]snapshotBlock, 0, index.Tip),
	}
	for height := int64(1); height <= index.Tip; height++ {
		block := index.Blocks[height]
		txs := make([]string, len(block.Txs))
		copy(txs, block.Txs)
		doc.Blocks = append(doc.Blocks, snapshotBlock{
			Height: block.Height,
			Hash:   block.Hash,
			Parent: block.Parent,
			Txs:    txs,
		})
	}
	index.mu.Unlock()

	raw, err := json.Marshal(doc)
	if err != nil {
		panic(err) // snapshotDoc only contains marshalable fields
	}
	n, err := w.Write(raw)
	if err != nil {
		return fmt.Errorf("indexroom: export snapshot: %w", err)
	}
	if n != len(raw) {
		return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
	}
	return nil
}
