			return block, invalidSnapshot("unknown block field %q", key)
		}
	}
	if _, err := dec.Token(); err != nil { // closing '}'
		return block, classifySnapshotErr(err)
	}
	for field, present := range map[string]bool{
		"height": haveHeight,
