package indexroom

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"reflect"
	"strings"
	"sync"
	"testing"
)

func exportString(t *testing.T, index *Index) string {
	t.Helper()
	var buf bytes.Buffer
	if err := index.Export(&buf); err != nil {
		t.Fatalf("export failed: %v", err)
	}
	return buf.String()
}

// genericSnapshot is a schema-free view of exported bytes for invariant
// checks that should not depend on the production struct tags.
type genericSnapshot struct {
	Version int64 `json:"version"`
	Tip     int64 `json:"tip"`
	Blocks  []struct {
		Height int64    `json:"height"`
		Hash   string   `json:"hash"`
		Parent string   `json:"parent"`
		Txs    []string `json:"txs"`
	} `json:"blocks"`
}

// requireWellFormedSnapshot checks the exported bytes describe one complete
// contiguous chain.
func requireWellFormedSnapshot(t *testing.T, raw string) genericSnapshot {
	t.Helper()
	var doc genericSnapshot
	if err := json.Unmarshal([]byte(raw), &doc); err != nil {
		t.Fatalf("exported snapshot does not parse: %v", err)
	}
	if doc.Version != 1 {
		t.Fatalf("exported version=%d, want 1", doc.Version)
	}
	for i, block := range doc.Blocks {
		if want := int64(i + 1); block.Height != want {
			t.Fatalf("exported block %d has height %d, want %d", i, block.Height, want)
		}
		if i > 0 && block.Parent != doc.Blocks[i-1].Hash {
			t.Fatalf("exported block at height %d breaks the parent link", block.Height)
		}
	}
	last := int64(0)
	if len(doc.Blocks) > 0 {
		last = doc.Blocks[len(doc.Blocks)-1].Height
	}
	if doc.Tip != last {
		t.Fatalf("exported tip=%d, last height=%d", doc.Tip, last)
	}
	return doc
}

