// failWriter fails every write after a successful prefix of n bytes.
type failWriter struct {
	n   int
	err error
}

func (w *failWriter) Write(p []byte) (int, error) {
	if w.n >= len(p) {
		w.n -= len(p)
		return len(p), nil
	}
	return 0, w.err
}

