// requireWellFormedSnapshot checks the exported bytes describe one complete
// contiguous chain.
func requireWellFormedSnapshot(t *testing.T, raw string) genericSnapshot {
	t.Helper()
	var doc genericSnapshot
	if err := json.Unmarshal([]byte(raw), &doc); err != nil {
		t.Fatalf("exported snapshot does not parse: %v", err)
	}
	if doc.Version != 1 {
		t.Fatalf("exported version=%d, want 1", doc.Version)
	}
	for i, block := range doc.Blocks {
		if want := int64(i + 1); block.Height != want {
			t.Fatalf("exported block %d has height %d, want %d", i, block.Height, want)
		}
		if i > 0 && block.Parent != doc.Blocks[i-1].Hash {
			t.Fatalf("exported block at height %d breaks the parent link", block.Height)
		}
	}
	last := int64(0)
	if len(doc.Blocks) > 0 {
		last = doc.Blocks[len(doc.Blocks)-1].Height
	}
	if doc.Tip != last {
		t.Fatalf("exported tip=%d, last height=%d", doc.Tip, last)
	}
	return doc
}

